{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Loganin, the closest structural analogue (Morgan 0.7857), showed poor BBB penetration in rats after systemic administration, with the lowest brain levels among tissues, indicating inadequate CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Geniposide, a related iridoid glycoside, was detected in mouse CSF after administration of HLJDD, demonstrating that some iridoid glycosides can cross the BBB.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C08"],
      "claim": "Scandoside methyl ester was detected in rat brain microdialysates and tissue homogenates, providing direct evidence of BBB permeation for a closely related iridoid glycoside.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C03"],
      "claim": "Deacetyl asperulosidic acid methyl ester was detected in rat brain microdialysates and tissue homogenates, also supporting BBB permeation among iridoid glycosides.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest analogue loganin is poorly brain-penetrant, and morroniside's additional ring oxygen increases polarity, making inadequate CNS access more likely; permeable results for other iridoid glycosides are less transferable due to lower structural similarity.",
  "evidence_gaps": [
    "No direct morroniside-specific brain or CSF measurement is available.",
    "Conflicting permeability results among iridoid glycosides create uncertainty.",
    "Transporter-mediated uptake or efflux mechanisms for morroniside are not characterized."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C04"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "iridoid glycoside"
    }
  ],
  "revision_action": "initial"
}

